        best_d = None
        for t in targets:
            if isinstance(t, (list, tuple)) and len(t) >= 2:
                d = abs(t[0] - sx) + abs(t[1] - sy)
                if best is None or d > best_d:
                    best = t
                    best_d = d
        return best

