    sx, sy = get_pos(("self_position", "position", "agent_position"), (0, 0))
    ox, oy = get_pos(("opponent_position", "enemy_position", "target_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
