        targets = observation.get("unclaimed_cells") or observation.get("neutral_cells") or observation.get("opponent_territory") or []
        target = closest(targets, sx, sy)
        if target is not None:
            return clamp_dir(sgn(target[0] - sx), sgn(target[1] - sy))
        # fallback: move toward opponent if no territory target is available
        return clamp_dir(sgn(ox - sx), sgn(oy - sy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("food") or []
    target = closest(resources, sx, sy)
    if target is not None:
        return clamp_dir(sgn(target[0] - sx), sgn(target[1] - sy))

